+import { test, before, after } from 'node:test';
+import assert from 'node:assert/strict';
+import { createServer } from './server.js';
+
+let server;
+let base;
+
+before(async () => {
+  server = createServer();
+  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
+  base = `http://127.0.0.1:${server.address().port}`;
+});
+
+after(() => new Promise((resolve) => server.close(resolve)));
+
+test('GET / serves the page as HTML', async () => {
+  const res = await fetch(`${base}/`);
+  assert.equal(res.status, 200);
+  assert.match(res.headers.get('content-type'), /^text\/html/);
+  assert.match(await res.text(), /<html/i);
+});
+
+test('GET /split.js serves the shared split module as JavaScript', async () => {
+  const res = await fetch(`${base}/split.js`);
+  assert.equal(res.status, 200);
+  assert.match(res.headers.get('content-type'), /^text\/javascript/);
+  assert.match(await res.text(), /export function splitBill/);
+});
+
+test('unknown path is 404', async () => {
+  const res = await fetch(`${base}/nope.txt`);
+  assert.equal(res.status, 404);
+});
+
+test('path traversal cannot escape public/', async () => {
+  for (const path of ['/../package.json', '/%2e%2e/package.json', '/..%2fpackage.json']) {
+    const res = await fetch(`${base}${path}`);
+    assert.equal(res.status, 404, path);
+    assert.doesNotMatch(await res.text(), /tip-splitter-2/, path);
+  }
+});
+
+test('non-GET methods are rejected', async () => {
+  const res = await fetch(`${base}/`, { method: 'POST' });
+  assert.equal(res.status, 405);
+});
