@@ -0,0 +1,111 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { splitBill } from './split.js';
+
+test('splits a normal bill evenly', () => {
+  assert.deepEqual(splitBill({ bill: 100, tipPercent: 20, people: 4 }), {
+    ok: true,
+    tip: 20,
+    total: 120,
+    perPerson: 30,
+  });
+});
+
+test('accepts string input straight from form fields', () => {
+  assert.deepEqual(splitBill({ bill: ' 50 ', tipPercent: '10', people: '2' }), {
+    ok: true,
+    tip: 5,
+    total: 55,
+    perPerson: 27.5,
+  });
+});
+
+test('zero tip is allowed', () => {
+  assert.deepEqual(splitBill({ bill: 30, tipPercent: 0, people: 3 }), {
+    ok: true,
+    tip: 0,
+    total: 30,
+    perPerson: 10,
+  });
+});
+
+test('one person pays the whole total', () => {
+  const r = splitBill({ bill: 42.5, tipPercent: 15, people: 1 });
+  assert.equal(r.ok, true);
+  assert.equal(r.tip, 6.38); // 6.375 rounds to nearest cent
+  assert.equal(r.total, 48.88);
+  assert.equal(r.perPerson, 48.88);
+});
+
+test('tip is rounded to the nearest cent', () => {
+  const r = splitBill({ bill: 10.01, tipPercent: 15, people: 1 });
+  assert.equal(r.tip, 1.5); // 1.5015 -> 1.50
+  assert.equal(r.total, 11.51);
+});
+
+test('avoids floating point drift (0.1 + 0.2 style)', () => {
+  const r = splitBill({ bill: 0.1, tipPercent: 200, people: 1 });
+  assert.equal(r.tip, 0.2);
+  assert.equal(r.total, 0.3);
+});
+
+test('per-person share rounds UP to the cent so the bill is always covered', () => {
+  const r = splitBill({ bill: 100, tipPercent: 0, people: 3 });
+  assert.equal(r.total, 100);
+  assert.equal(r.perPerson, 33.34); // 3 x 33.34 = 100.02 >= 100
+  assert.ok(r.perPerson * 3 >= r.total);
+});
+
+test('exact splits are not rounded up', () => {
+  const r = splitBill({ bill: 99.99, tipPercent: 0, people: 3 });
+  assert.equal(r.perPerson, 33.33);
+});
+
+test('fractional tip percent works', () => {
+  const r = splitBill({ bill: 200, tipPercent: 12.5, people: 2 });
+  assert.equal(r.tip, 25);
+  assert.equal(r.perPerson, 112.5);
+});
+
+// ---- bad input: never throws, returns { ok: false, field, message } ----
+
+const bad = [
+  ['empty bill', { bill: '', tipPercent: 15, people: 2 }, 'bill'],
+  ['missing bill', { tipPercent: 15, people: 2 }, 'bill'],
+  ['non-numeric bill', { bill: 'abc', tipPercent: 15, people: 2 }, 'bill'],
+  ['negative bill', { bill: -5, tipPercent: 15, people: 2 }, 'bill'],
+  ['infinite bill', { bill: Infinity, tipPercent: 15, people: 2 }, 'bill'],
+  ['empty tip', { bill: 50, tipPercent: '', people: 2 }, 'tipPercent'],
+  ['negative tip', { bill: 50, tipPercent: -10, people: 2 }, 'tipPercent'],
+  ['NaN tip', { bill: 50, tipPercent: NaN, people: 2 }, 'tipPercent'],
+  ['zero people', { bill: 50, tipPercent: 15, people: 0 }, 'people'],
+  ['negative people', { bill: 50, tipPercent: 15, people: -2 }, 'people'],
+  ['fractional people', { bill: 50, tipPercent: 15, people: 2.5 }, 'people'],
+  ['empty people', { bill: 50, tipPercent: 15, people: '' }, 'people'],
+  ['null people', { bill: 50, tipPercent: 15, people: null }, 'people'],
+];
+
+for (const [name, input, field] of bad) {
+  test(`bad input: ${name}`, () => {
+    const r = splitBill(input);
+    assert.equal(r.ok, false);
+    assert.equal(r.field, field);
+    assert.equal(typeof r.message, 'string');
+    assert.ok(r.message.length > 0);
+  });
+}
+
+test('called with nothing at all does not throw', () => {
+  const r = splitBill();
+  assert.equal(r.ok, false);
+  assert.equal(r.field, 'bill');
+});
+
+test('zero bill is valid and splits to zero', () => {
+  assert.deepEqual(splitBill({ bill: 0, tipPercent: 15, people: 2 }), {
+    ok: true,
+    tip: 0,
+    total: 0,
+    perPerson: 0,
+  });
+});
